(()=>{const tiles=[...document.querySelectorAll('[data-gallery-src]')];const dialog=document.getElementById('dialog'),content=document.getElementById('dialog-content');if(!dialog||!content)return;let current=0;
const render=index=>{const visible=tiles.filter(tile=>!tile.hidden);current=(index+visible.length)%visible.length;const tile=visible[current];content.replaceChildren();const image=document.createElement('img');image.src=tile.dataset.gallerySrc;image.alt=tile.dataset.galleryCaption;image.className='gallery-full-image';const caption=document.createElement('p');caption.textContent=tile.dataset.galleryCaption;const controls=document.createElement('div');controls.className='gallery-view-controls';[['Previous',-1],['Next',1]].forEach(([text,step])=>{const button=document.createElement('button');button.type='button';button.textContent=text;button.addEventListener('click',()=>render(current+step));controls.append(button)});const count=document.createElement('span');count.textContent=`${current+1} / ${visible.length}`;controls.insertBefore(count,controls.lastChild);content.append(image,caption,controls)};
tiles.forEach(tile=>tile.addEventListener('click',()=>{render(tiles.filter(t=>!t.hidden).indexOf(tile));dialog.classList.add('campus-gallery-dialog');dialog.showModal()}));dialog.addEventListener('close',()=>dialog.classList.remove('campus-gallery-dialog'));dialog.addEventListener('keydown',event=>{if(!dialog.classList.contains('campus-gallery-dialog'))return;if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();render(current+(event.key==='ArrowRight'?1:-1))}});
document.querySelectorAll('[data-gallery-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));tiles.forEach(tile=>tile.hidden=button.dataset.galleryFilter!=='All'&&tile.dataset.galleryCategory!==button.dataset.galleryFilter)}));})();
